def transform(grid):
 g=[row[:] for row in grid]; R=len(g); C=len(g[0]); pts=[(r,c) for r in range(R) for c in range(C) if g[r][c]==5]; ar=min(r for r,c in pts); ac=min(c for r,c in pts); shape=[(r-ar,c-ac) for r,c in pts]
 for r in range(R-max(x for x,y in shape)):
